const VIDEO_RE = /\.(mp4|mov|m4v|webm|avi|mkv|mpeg|mpg)$/i;
function hugoBasename(name) {
  const n = String(name || '');
  if (!n) return n;
  if (VIDEO_RE.test(n)) return n.replace(/\.[^.]+$/, '') + '.mp4';
  return n;
}
function asBlocks(value) {
  if (Array.isArray(value)) return value;
  if (typeof value === 'string' && value.trim()) {
    try {
      const parsed = JSON.parse(value);
      return Array.isArray(parsed) ? parsed : [];
    } catch (e) {
      return [];
    }
  }
  return [];
}

// Prefer $input (what the previous node actually passed). Typed workflowInputs
// on Execute Workflow Trigger often ignore pinData and arrive as nulls.
const raw = $input.first().json || {};
const slug = String(raw.slug || '').trim();
const blocks = asBlocks(raw.blocks);
const header = String(raw.header_source || '').trim();

if (!slug) {
  throw new Error(
    'Adapt Hugo Media: missing slug. Trigger received empty workflowInputs ' +
    '(slug/blocks/header_source). When testing manually, fill the trigger input ' +
    'fields — pinData on Execute Workflow Trigger is not applied to typed inputs.'
  );
}

const base = '/syndicator';
const siteRoot = `${base}/hugo-site/content/posts/${slug}`;
const sourceRoot = `${base}/${slug}/source`;
const jobs = [];

for (const b of blocks) {
  if (b?.kind !== 'media' || !b.media) continue;
  const m = b.media;
  const source_filename = String(m.source_filename || '').trim();
  if (!source_filename) continue;
  const bundle_filename = hugoBasename(source_filename);
  const kind = m.kind || (VIDEO_RE.test(source_filename) ? 'video' : 'image');
  jobs.push({
    kind,
    source_sftp_path: `${sourceRoot}/${source_filename}`,
    sftp_path: `${siteRoot}/${bundle_filename}`,
    bundle_filename,
    role: '',
    slug,
  });
}

if (header) {
  const ext = header.includes('.') ? header.slice(header.lastIndexOf('.')) : '.jpg';
  jobs.push({
    kind: 'image',
    source_sftp_path: `${sourceRoot}/${header}`,
    sftp_path: `${siteRoot}/featured${ext}`,
    bundle_filename: `featured${ext}`,
    role: 'featured',
    slug,
  });
}

if (!jobs.length) return [{ json: { kind: 'noop', skip: true } }];
const fs = require('fs');
const path = require('path');
for (const job of jobs) {
  fs.mkdirSync(path.dirname(job.sftp_path), { recursive: true });
}
return jobs.map((j) => ({ json: j }));

const job = $input.item.json;
function quote(p) {
  return '"' + String(p).replace(/\\/g, '\\\\').replace(/"/g, '\\"') + '"';
}
const customArgs = `-y -i ${quote(job.source_sftp_path)} -vf "scale=700:394:force_original_aspect_ratio=decrease" -c:v libx264 -preset veryfast -crf 28 -pix_fmt yuv420p -c:a aac -movflags +faststart ${quote(job.sftp_path)}`;
return { json: { ...job, customArgs } };

const fs = require('fs');
return $input.all().map((item) => {
  const job = item.json;
  fs.copyFileSync(job.source_sftp_path, job.sftp_path);
  return { json: job };
});
